import{H as e,gt as t,nt as n,rt as r}from"./chunks/framework.CFVsAkBd.js";var i=JSON.parse(`{"title":"Physics scales","description":"","frontmatter":{"title":"Physics scales","head":[["meta",{"property":"og:title","content":"Physics scales | Millennium Solutions"}],["meta",{"property":"og:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["meta",{"property":"og:url","content":"https://ceccec.psg.bg/millennium-solutions/PHYSICS-SCALES.html"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:title","content":"Physics scales | Millennium Solutions"}],["meta",{"name":"twitter:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["link",{"rel":"canonical","href":"https://ceccec.psg.bg/millennium-solutions/PHYSICS-SCALES.html"}],["link",{"rel":"alternate","hreflang":"en","href":"https://ceccec.psg.bg/millennium-solutions/PHYSICS-SCALES.html"}],["link",{"rel":"alternate","hreflang":"bg","href":"https://ceccec.psg.bg/millennium-solutions/bg/PHYSICS-SCALES.html"}],["link",{"rel":"alternate","hreflang":"de","href":"https://ceccec.psg.bg/millennium-solutions/de/PHYSICS-SCALES.html"}],["link",{"rel":"alternate","hreflang":"fr","href":"https://ceccec.psg.bg/millennium-solutions/fr/PHYSICS-SCALES.html"}],["link",{"rel":"alternate","hreflang":"es","href":"https://ceccec.psg.bg/millennium-solutions/es/PHYSICS-SCALES.html"}],["link",{"rel":"alternate","hreflang":"ru","href":"https://ceccec.psg.bg/millennium-solutions/ru/PHYSICS-SCALES.html"}],["link",{"rel":"alternate","hreflang":"zh","href":"https://ceccec.psg.bg/millennium-solutions/zh/PHYSICS-SCALES.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://ceccec.psg.bg/millennium-solutions/PHYSICS-SCALES.html"}]]},"headers":[],"relativePath":"PHYSICS-SCALES.md","filePath":"PHYSICS-SCALES.md"}`),a={name:`PHYSICS-SCALES.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="physics-scales-shell-model-magic-numbers-matter-as-waves-and-where-a432-sits" tabindex="-1">Physics scales: shell-model magic numbers, matter-as-waves, and where A432 sits <a class="header-anchor" href="#physics-scales-shell-model-magic-numbers-matter-as-waves-and-where-a432-sits" aria-label="Permalink to “Physics scales: shell-model magic numbers, matter-as-waves, and where A432 sits”">​</a></h1><p>Companion to <code>SEQUENCE-DECODE.md</code>. Every value here is computed; reproduce with <code>node shell-model-magic.ts</code> and <code>node frequency-scales.ts</code>. The animation of the merkaba → Flower → Fruit → Metatron construction is <code>merkaba-flower.html</code>.</p><h2 id="_1-the-nuclear-magic-numbers-come-from-the-shell-model" tabindex="-1">1. The nuclear magic numbers come from the shell model <a class="header-anchor" href="#_1-the-nuclear-magic-numbers-come-from-the-shell-model" aria-label="Permalink to “1. The nuclear magic numbers come from the shell model”">​</a></h2><p>Filling nucleons into 3D-harmonic-oscillator levels split by spin-orbit coupling (level capacity <code>2j+1</code>), the cumulative count lands exactly on every magic number:</p><div class="language- line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1s½ →2★   1p³⁄₂→6   1p½→8★   1d⁵⁄₂→14  2s½→16  1d³⁄₂→20★</span></span>
<span class="line"><span>1f⁷⁄₂→28★ (spin-orbit intruder)</span></span>
<span class="line"><span>2p³⁄₂→32  1f⁵⁄₂→38  2p½→40   1g⁹⁄₂→50★ (intruder)</span></span>
<span class="line"><span>1g⁷⁄₂→58  2d⁵⁄₂→64  2d³⁄₂→68  3s½→70   1h¹¹⁄₂→82★ (intruder)</span></span>
<span class="line"><span>1h⁹⁄₂→92  2f⁷⁄₂→100 2f⁵⁄₂→106 3p³⁄₂→110 3p½→112  1i¹³⁄₂→126★ (intruder)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><code>2, 8, 20, 28, 50, 82, 126</code> — all seven. Two ingredients: the oscillator (gives 2, 8, 20) and spin-orbit coupling (the high-<code>j</code> intruders <code>1f⁷⁄₂, 1g⁹⁄₂, 1h¹¹⁄₂, 1i¹³⁄₂</code> producing 28, 50, 82, 126). Goeppert-Mayer &amp; Jensen, Nobel Prize 1963.</p><ul><li>Plain harmonic oscillator (no spin-orbit): <code>2, 8, 20, 40, 70, 112</code>.</li><li>Observed (with spin-orbit): <code>2, 8, 20, 28, 50, 82, 126</code>.</li><li>They agree only for <code>2, 8, 20</code>; spin-orbit then replaces <code>40, 70, 112</code>.</li></ul><h2 id="_2-the-5-arithmetic-ladder-vs-the-magic-numbers" tabindex="-1">2. The 5-arithmetic ladder vs the magic numbers <a class="header-anchor" href="#_2-the-5-arithmetic-ladder-vs-the-magic-numbers" aria-label="Permalink to “2. The 5-arithmetic ladder vs the magic numbers”">​</a></h2><p><code>5+5 = 10</code>, and <code>10·2^k = 10, 20, 40, 80, 160, …</code> is the ×2 doubling / octave ladder (the same <code>⟨2⟩</code> circuit as in <code>SEQUENCE-DECODE.md</code>, seeded at 10). (Arithmetic note: <code>2·2·2·2·(5+5) = 160</code>, not 80; <code>80 = 2·2·2·(5+5)</code>.)</p><ul><li>ladder ∩ oscillator closures <code>{2,8,20,40,70,112}</code> = <code>{20, 40}</code>.</li><li>ladder ∩ observed magic <code>{2,8,20,28,50,82,126}</code> = <code>{20}</code>.</li><li>The ladder misses <code>2, 8, 28, 50, 82, 126</code> and includes non-magic <code>10, 80, 160</code>.</li></ul><p>So the ladder brushes the oscillator closures at 20 and 40 by sharing small factors of 2; it does not reproduce the magic-number sequence, which requires spin-orbit coupling. Coincidence, not derivation.</p><h2 id="_3-matter-is-wave-phenomena-—-and-the-waves-have-scales" tabindex="-1">3. Matter is wave phenomena — and the waves have scales <a class="header-anchor" href="#_3-matter-is-wave-phenomena-—-and-the-waves-have-scales" aria-label="Permalink to “3. Matter is wave phenomena — and the waves have scales”">​</a></h2><p>Bound matter is standing waves (orbitals, nuclear shells are de Broglie standing waves; a bound nucleon&#39;s wavelength ≈ 5 fm fits a few-fm nucleus). Particles are field excitations (QFT); ~99% of a proton&#39;s mass is gluon-field energy, not quark rest mass. Cancellation builds structure (nodes; the merkaba field-null on the 3-6-9 axis in <code>MERKABA-FIELD</code> is a real destructive-interference null).</p><p>Following the wave, each system&#39;s frequency is <code>f = E/h</code>:</p><table tabindex="0"><thead><tr><th>wave that forms…</th><th>energy</th><th>frequency</th></tr></thead><tbody><tr><td>a 432 Hz tone</td><td>1.79×10⁻¹² eV</td><td>4.3×10² Hz</td></tr><tr><td>visible light</td><td>~2 eV</td><td>4.8×10¹⁴ Hz</td></tr><tr><td>a chemical bond</td><td>~10 eV</td><td>2.4×10¹⁵ Hz</td></tr><tr><td>a nuclear shell</td><td>~3 MeV</td><td>7×10²⁰ Hz</td></tr><tr><td>a proton</td><td>938 MeV</td><td>2.3×10²³ Hz</td></tr></tbody></table><p>The waves that form a nucleus ring at <code>~10²⁰–10²³ Hz</code>. Ratios to 432 Hz: nuclear shell ≈ <code>10¹⁸</code>; proton ≈ <code>10²¹</code>.</p><h2 id="_4-scope-boundary" tabindex="-1">4. Scope / boundary <a class="header-anchor" href="#_4-scope-boundary" aria-label="Permalink to “4. Scope / boundary”">​</a></h2><ul><li>The shell-model derivation (§1) is exact, standard physics and is complete — the magic numbers need no external energy source.</li><li><code>E = hf</code> and <code>c = λf</code> assign each system its own frequency; frequency is a universal quantity but frequencies are not interchangeable. 432 Hz is the acoustic scale (~10² Hz); nuclear structure is ~10²⁰–10²³ Hz — a gap of ~18–21 orders of magnitude, with no coupling mechanism between an audio pitch and the strong-force spin-orbit term (whose origin is the operator <code>l·s</code>, not a frequency).</li><li>The ℤ/9 vortex arithmetic and the merkaba/cube geometry (<code>SEQUENCE-DECODE.md</code>) are exact; the A432 tuning is real acoustics (<code>A432-RESEARCH</code> in the <code>ceccec.github.io</code> repo). None of it bears on the Clay problems; the entailment test remains 0/7 (<code>entails.ts</code>).</li></ul>`,18)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};